\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── UNICEF Color Theme (Cyan/Blue + Warm Amber) ──
\definecolor{primary}{HTML}{00619C}      % deep UNICEF blue
\definecolor{secondary}{HTML}{00ACEE}     % UNICEF cyan
\definecolor{accent}{HTML}{F5A623}       % warm amber
\definecolor{accent2}{HTML}{E85D04}     % deeper orange
\definecolor{bgposter}{HTML}{F0F9FF}    % light cyan tint
\definecolor{redbg}{HTML}{FFF5EB}       % warm cream
\definecolor{bluebg}{HTML}{E8F6FC}       % light blue tint
\definecolor{darkbg}{HTML}{FDF6F0}      % warm cream for dark cards
\definecolor{redtitlebg}{HTML}{FDE8CC}   % amber title tint
\definecolor{bluetitlebg}{HTML}{D4F1FA}  % blue title tint
\definecolor{darktitlebg}{HTML}{F5E0CC}  % dark title tint
\definecolor{textdark}{HTML}{1A1A2E}    % near-black
\definecolor{textgray}{HTML}{4A5568}    % medium gray
\definecolor{stathighlight}{HTML}{FEF3E2}% warm stat highlight
\definecolor{white}{HTML}{FFFFFF}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=8pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}\textbullet}}
\setlist[enumerate]{leftmargin=20pt, itemsep=8pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{22}{28}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ── Card styles (left accent stripe design) ──
\tcbset{
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={6pt}{0pt}{accent},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=redtitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.15},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={6pt}{0pt}{secondary},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=bluetitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={6pt}{0pt}{primary},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=darktitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!18!white,
    borderline west={8pt}{0pt}{primary},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=0pt,
    valign=top, drop shadow={opacity=0.2},
  },
  cta-card/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=accent!15!white,
    borderline west={8pt}{0pt}{accent2},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accent2},
    coltitle=accent2, colbacktitle=stathighlight,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent2!50},
    valign=top, drop shadow={opacity=0.18},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=10pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=title, column=1, span=3, between=top and row5}{
  {\fontsize{76}{92}\selectfont\bfseries Every Child Deserves to Learn}\\[10pt]
  {\fontsize{30}{38}\selectfont\color{white!85} 250 Million Children Are Out of School — Together, We Can Change This}
}

% ══ STAT BANNER ══
\posterbox[
  enhanced, colback=white, boxrule=0pt, arc=0pt,
  left=8pt, right=8pt, top=4pt, bottom=4pt,
  valign=center, borderline={3pt}{0pt}{primary!30},
  drop shadow={opacity=0.1}
]{name=stats, column=1, span=3, between=row5 and row8}{
  \centering
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{primary!50}{stathighlight}{\parbox{0.9\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{58}{72}\selectfont\bfseries\color{primary} 250M}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textdark} Children out of school}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{secondary!50}{bluebg}{\parbox{0.9\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{58}{72}\selectfont\bfseries\color{secondary} 70\%}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textdark} Cannot read by age 10}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{accent!50}{redbg}{\parbox{0.9\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{58}{72}\selectfont\bfseries\color{accent} 190+}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textdark} Countries with UNICEF programmes}\vspace{8pt}%
    }}
  \end{minipage}
}

% ══ THE CRISIS ══
\posterbox[bluecard, title={The Global Education Crisis}
]{name=crisis, column=1, between=row8 and row13}{
  \fontsize{30}{40}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item 250 million children and adolescents are out of school worldwide
    \item 70\% of children in low- and middle-income countries cannot read a simple text by age 10
    \item These numbers represent lost potential for individuals, communities, and economies
  \end{itemize}
}

% ══ BARRIERS ══
\posterbox[redcard, title={Barriers to Education}
]{name=barriers, column=2, between=row8 and row13}{
  \fontsize{28}{38}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item \textbf{Conflict:} Schools destroyed, teachers displaced, children traumatized
    \item \textbf{Poverty:} Families cannot afford fees, uniforms, or supplies
    \item \textbf{Gender inequality:} Deep norms limit girls' access, especially secondary school
    \item \textbf{Disability:} Nearly half of children with disabilities never set foot in a classroom
    \item \textbf{Climate change:} Floods, droughts disrupt schooling for the most vulnerable
  \end{itemize}
}

% ══ GIRLS STAT ══
\posterbox[highlightcard, title={Girls in Crisis Settings}
]{name=girls, column=3, between=row8 and row11}{
  \centering\vspace{6pt}
  {\fontsize{64}{78}\selectfont\bfseries\color{white} 2.5×}\\[6pt]
  {\fontsize{26}{34}\selectfont\color{white!90} more likely for girls to be excluded from education in conflict zones}\\[6pt]
  \vspace{6pt}
}

% ══ UNICEF FOCUS AREAS ══
\posterbox[darkcard, title={UNICEF's Focus Areas}
]{name=focus, column=3, between=row11 and row16}{
  \fontsize{26}{36}\selectfont
  \begin{itemize}[itemsep=6pt]
    \item Early childhood development
    \item Inclusive education for all
    \item Gender equality
    \item Education in emergencies
    \item Digital learning
    \item Adolescent skills
  \end{itemize}
}

% ══ CALL TO ACTION ══
\posterbox[cta-card, title={What Can Be Done}
]{name=cta, column=1, span=2, between=row13 and row18}{
  \fontsize{28}{38}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item \textbf{Invest in education} — it means investing in peace, innovation, and sustainable development
    \item \textbf{Support SDG 4} — inclusive, equitable quality education for all
    \item \textbf{Together} — governments, communities, organizations, and individuals can ensure no child is left behind
  \end{itemize}
}

% ══ BOTTOM EMPHASIS ══
\posterbox[
  enhanced, colback=secondary, colframe=secondary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=8pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.25}
]{name=bottom, column=1, span=3, between=row18 and bottom}{
  {\fontsize{36}{44}\selectfont\bfseries Every child who misses out on education is a missed opportunity}\\[6pt]
  {\fontsize{26}{34}\selectfont\color{white!85} Source: UNICEF Education Programme (unicef.org/education)}
}

\end{tcbposter}
\end{document}

